LOGO_SPS_B64 = ""

LOGO_EP_B64 = ""

SMMLV = 1_750_905.00
AUXILIO_TRANSPORTE = 249_095.00
LIMITE_2_SMMLV = SMMLV * 2

HORAS_MENSUALES = 210
MAX_HORAS_DIARIAS = 8
MAX_HORAS_SEMANALES = 42

CESANTIAS = 0.08333333
INTERESES_CESANTIAS = 0.01
PRIMA = 0.08333333
VACACIONES = 0.04166667

PENSION = 0.12
SALUD_NO_EXONERADA = 0.085
PARAFISCALES = 0.04
DOTACION_EPP = 0.08

POLIZAS = 0.015
ADMINISTRACION = 0.10
IVA = 0.19
IVA_SOBRE_AIU = 0.10

ARL = {
    "I": 0.00522,
    "II": 0.01044,
    "III": 0.02436,
    "IV": 0.04350,
    "V": 0.06960
}

FACTORES = {
    "Ordinaria diurna": 1.00,
    "Ordinaria nocturna": 1.35,
    "Extra diurna": 1.25,
    "Extra nocturna": 1.75,
    "Dominical/festiva diurna": 1.90,
    "Dominical/festiva nocturna": 1.90,
    "Dominical/festiva extra diurna": 2.15,
    "Dominical/festiva extra nocturna": 2.65
}

DIAS = [
    "Lunes",
    "Martes",
    "Miércoles",
    "Jueves",
    "Viernes",
    "Sábado",
    "Domingo"
]


