def money(valor):
    return f"${valor:,.2f}"


def hours(valor):
    return f"{valor:.2f}"


def obtener_minutos_jornada(fecha_servicio, entrada, salida):

    inicio = datetime.combine(fecha_servicio, entrada)
    fin = datetime.combine(fecha_servicio, salida)

    if fin <= inicio:
        fin += timedelta(days=1)

    minutos = []
    actual = inicio

    while actual < fin:
        minutos.append(actual)
        actual += timedelta(minutes=1)

    return minutos


def es_diurna(momento):
    return 6 <= momento.hour < 19


def clasificar_turnos(horarios, fecha_inicio, fecha_final, festivos):

    minutos = []

    fecha_actual = fecha_inicio

    while fecha_actual <= fecha_final:

        dia = DIAS[fecha_actual.weekday()]
        datos = horarios[dia]

        if datos["trabaja"]:

            minutos.extend(
                obtener_minutos_jornada(
                    fecha_actual,
                    datos["entrada"],
                    datos["salida"]
                )
            )

        fecha_actual += timedelta(days=1)

    diarios = {}
    semanales = {}

    for momento in minutos:

        fecha_real = momento.date()

        lunes_semana = (
            fecha_real -
            timedelta(days=fecha_real.weekday())
        )

        diarios[fecha_real] = (
            diarios.get(fecha_real, 0) + 1
        )

        semanales[lunes_semana] = (
            semanales.get(lunes_semana, 0) + 1
        )

    usados_diarios = {}
    usados_semanales = {}

    resultados = []

    for momento in minutos:

        fecha_real = momento.date()

        lunes_semana = (
            fecha_real -
            timedelta(days=fecha_real.weekday())
        )

        usados_diarios.setdefault(fecha_real, 0)
        usados_semanales.setdefault(lunes_semana, 0)

        es_extra_diaria = (
            usados_diarios[fecha_real]
            >= MAX_HORAS_DIARIAS * 60
        )

        es_extra_semanal = (
            usados_semanales[lunes_semana]
            >= MAX_HORAS_SEMANALES * 60
        )

        es_extra = (
            es_extra_diaria or es_extra_semanal
        )

        domingo = fecha_real.weekday() == 6
        festivo = fecha_real in festivos
        dominical_festivo = domingo or festivo

        diurna = es_diurna(momento)

        if dominical_festivo:

            if es_extra and diurna:
                categoria = "Dominical/festiva extra diurna"

            elif es_extra and not diurna:
                categoria = "Dominical/festiva extra nocturna"

            elif diurna:
                categoria = "Dominical/festiva diurna"

            else:
                categoria = "Dominical/festiva nocturna"

        else:

            if es_extra and diurna:
                categoria = "Extra diurna"

            elif es_extra and not diurna:
                categoria = "Extra nocturna"

            elif diurna:
                categoria = "Ordinaria diurna"

            else:
                categoria = "Ordinaria nocturna"

        resultados.append({
            "momento": momento,
            "fecha": fecha_real,
            "categoria": categoria,
            "diurna": diurna,
            "extra": es_extra
        })

        usados_diarios[fecha_real] += 1
        usados_semanales[lunes_semana] += 1

    return resultados


def resumen_categorias(registros):

    resumen = {
        categoria: 0
        for categoria in FACTORES
    }

    for registro in registros:
        resumen[registro["categoria"]] += 1

    for categoria in resumen:
        resumen[categoria] /= 60

    return resumen


def calcular_costos(
    salario,
    personas,
    resumen,
    riesgo,
    exonerada,
    duracion_dias,
    insumos,
    otros_costos,
    rodamiento,
    admin_rate
):

    valor_hora = salario / HORAS_MENSUALES

    dias_proporcion = duracion_dias / 30

    salario_periodo = (
        salario *
        dias_proporcion
    )

    if salario <= LIMITE_2_SMMLV:
        transporte_periodo = (
            AUXILIO_TRANSPORTE *
            dias_proporcion
        )
    else:
        transporte_periodo = 0.00

    costo_horas_adicionales = 0.00

    for categoria, cantidad in resumen.items():

        factor = FACTORES[categoria]

        if categoria == "Ordinaria diurna":
            continue

        if categoria == "Ordinaria nocturna":

            costo_horas_adicionales += (
                valor_hora *
                cantidad *
                (factor - 1)
            )

        elif categoria in [
            "Dominical/festiva diurna",
            "Dominical/festiva nocturna"
        ]:

            costo_horas_adicionales += (
                valor_hora *
                cantidad *
                (factor - 1)
            )

        else:

            costo_horas_adicionales += (
                valor_hora *
                cantidad *
                factor
            )

    base_prestaciones = (
        salario_periodo +
        transporte_periodo
    )

    cesantias = (
        base_prestaciones *
        CESANTIAS
    )

    intereses = (
        base_prestaciones *
        INTERESES_CESANTIAS
    )

    prima = (
        base_prestaciones *
        PRIMA
    )

    vacaciones = (
        salario_periodo *
        VACACIONES
    )

    pension = (
        salario_periodo *
        PENSION
    )

    if exonerada == "Sí":
        salud = 0.00
    else:
        salud = (
            salario_periodo *
            SALUD_NO_EXONERADA
        )

    arl = (
        salario_periodo *
        ARL[riesgo]
    )

    parafiscales = (
        salario_periodo *
        PARAFISCALES
    )

    dotacion_epp = (
        salario_periodo *
        DOTACION_EPP
    )

    polizas_base = (
        salario_periodo +
        transporte_periodo +
        costo_horas_adicionales +
        cesantias +
        intereses +
        prima +
        vacaciones +
        pension +
        salud +
        arl +
        parafiscales +
        dotacion_epp +
        rodamiento +
        insumos +
        otros_costos
    )

    polizas = (
        polizas_base *
        POLIZAS
    )

    costo_persona = (
        polizas_base +
        polizas
    )

    costo_real = (
        costo_persona *
        personas
    )

    administracion = (
        costo_real *
        admin_rate
    )

    base_aiu = (
        costo_real +
        administracion
    )

    iva = (
        base_aiu *
        IVA_SOBRE_AIU *
        IVA
    )

    total = (
        base_aiu +
        iva
    )

    return {
        "valor_hora": valor_hora,
        "salario_periodo": salario_periodo * personas,
        "transporte": transporte_periodo * personas,
        "horas_adicionales": costo_horas_adicionales * personas,
        "cesantias": cesantias * personas,
        "intereses": intereses * personas,
        "prima": prima * personas,
        "vacaciones": vacaciones * personas,
        "pension": pension * personas,
        "salud": salud * personas,
        "arl": arl * personas,
        "parafiscales": parafiscales * personas,
        "dotacion_epp": dotacion_epp * personas,
        "rodamiento": rodamiento * personas,
        "insumos": insumos,
        "otros_costos": otros_costos,
        "polizas": polizas * personas,
        "costo_real": costo_real,
        "administracion": administracion,
        "base_aiu": base_aiu,
        "iva": iva,
        "total": total
    }


def descripcion_comercial(servicio, fecha_inicio, fecha_final, insumos=0.0, rodamiento=0.0, otros_costos=0.0):
    """Genera una descripción comercial corta para pantalla y PDF."""
    nombre = (servicio or "SERVICIO").strip()
    if fecha_inicio == fecha_final:
        texto = f"{nombre} - {fecha_inicio.strftime('%d/%m/%Y')}"
    else:
        texto = (
            f"{nombre} - desde {fecha_inicio.strftime('%d/%m/%Y')} "
            f"hasta {fecha_final.strftime('%d/%m/%Y')}"
        )

    adicionales = []
    if insumos > 0.005:
        adicionales.append("insumos")
    if rodamiento > 0.005:
        adicionales.append("rodamiento")
    if otros_costos > 0.005:
        adicionales.append("otros costos")

    if adicionales:
        if len(adicionales) == 1:
            texto += f" con {adicionales[0]}"
        elif len(adicionales) == 2:
            texto += f" con {adicionales[0]} y {adicionales[1]}"
        else:
            texto += f" con {', '.join(adicionales[:-1])} y {adicionales[-1]}"

    return texto


def obtener_meses_periodo(fecha_inicio, fecha_final):
    """Devuelve los meses calendario incluidos en el periodo."""
    meses = []
    actual = fecha_inicio.replace(day=1)
    final = fecha_final.replace(day=1)
    nombres = [
        "Enero", "Febrero", "Marzo", "Abril", "Mayo", "Junio",
        "Julio", "Agosto", "Septiembre", "Octubre", "Noviembre", "Diciembre"
    ]
    while actual <= final:
        meses.append(f"{nombres[actual.month - 1]} {actual.year}")
        if actual.month == 12:
            actual = actual.replace(year=actual.year + 1, month=1)
        else:
            actual = actual.replace(month=actual.month + 1)
    return meses


