    # RESUMEN COMERCIAL
    # -----------------------------------------------------

    elementos.append(
        Paragraph(
            "<b>RESUMEN COMERCIAL</b>",
            styles["Heading3"]
        )
    )

    descripcion = descripcion_comercial(
        servicio,
        fecha_inicio,
        fecha_final,
        costos["insumos"],
        costos["rodamiento"],
        costos["otros_costos"]
    )

    resumen = [
        ["Concepto", "Valor"],
        ["Servicio", descripcion],
    ]

    if costos["insumos"] > 0.005:
        resumen.append(["Insumos", money(costos["insumos"])])
    if costos["rodamiento"] > 0.005:
        resumen.append(["Rodamiento", money(costos["rodamiento"])])
    if costos["otros_costos"] > 0.005:
        resumen.append(["Otros costos", money(costos["otros_costos"])])

    # Si el servicio abarca más de un mes calendario, mostrar el valor
    # distribuido por cada mes sin cambiar el total de la cotización.
    meses_periodo = obtener_meses_periodo(fecha_inicio, fecha_final)
    if len(meses_periodo) > 1:
        valor_por_mes = total_comercial / len(meses_periodo)
        resumen.append(["Valor por mes", ""])
        for mes_nombre in meses_periodo:
            resumen.append([mes_nombre, money(valor_por_mes)])

    resumen.extend([
        [
            f"Administración / AIU {admin_rate * 100:.2f}%",
            money(administracion_comercial)
        ],
        [
            "BASE AIU",
            money(base_aiu_comercial)
        ],
        [
            "IVA",
            money(iva_comercial)
        ],
        [
            "TOTAL",
            money(total_comercial)
        ]
    ])

    resumen[1][1] = Paragraph(
        str(resumen[1][1]),
        ParagraphStyle(
            "DescripcionComercial",
            parent=styles["Normal"],
            fontSize=9.5,
            leading=12
        )
    )

    tabla_resumen = Table(
        resumen,
        colWidths=[
            110 * mm,
            70 * mm
        ]
    )

    tabla_resumen.setStyle(
        TableStyle([
            (
                "BACKGROUND",
                (0, 0),
                (-1, 0),
                color_principal
            ),
            (
                "TEXTCOLOR",
                (0, 0),
                (-1, 0),
                colors.white
            ),
            (
                "FONTNAME",
                (0, 0),
                (-1, 0),
                "Helvetica-Bold"
            ),
            (
                "GRID",
                (0, 0),
                (-1, -1),
                0.5,
                colors.lightgrey
            ),
            (
                "ALIGN",
                (1, 1),
                (1, -1),
                "RIGHT"
            ),
            (
                "ALIGN",
                (1, 1),
                (1, 1),
                "LEFT"
            ),
            (
                "ROWBACKGROUNDS",
                (0, 1),
                (-1, -2),
                [colors.white, color_claro]
            ),
            (
                "BACKGROUND",
                (0, -1),
                (-1, -1),
                color_claro
            ),
            (
                "TEXTCOLOR",
                (0, -1),
                (-1, -1),
                color_principal
            ),
            (
                "FONTNAME",
                (0, -1),
                (-1, -1),
                "Helvetica-Bold"
            ),
            (
                "FONTSIZE",
                (0, -1),
                (-1, -1),
                14
            ),
            (
                "TOPPADDING",
                (0, -1),
                (-1, -1),
                10
            ),
            (
                "BOTTOMPADDING",
                (0, -1),
                (-1, -1),
                10
            )
        ])
    )

    elementos.append(tabla_resumen)
    elementos.append(Spacer(1, 16))

    # -----------------------------------------------------
    # TOTAL DESTACADO
    # -----------------------------------------------------

    total_tabla = Table(
        [
            [
                Paragraph(
                    "<b>TOTAL COTIZACIÓN</b>",
                    subtitulo
                )
            ],
            [
                Paragraph(
                    f"<b>{money(total_comercial)}</b>",
                    total_style
                )
            ]
        ],
        colWidths=[180 * mm]
    )

    total_tabla.setStyle(
        TableStyle([
            (
                "BACKGROUND",
                (0, 0),
                (-1, -1),
                color_claro
            ),
            (
                "BOX",
                (0, 0),
                (-1, -1),
                2,
                color_principal
            ),
            (
                "ALIGN",
                (0, 0),
                (-1, -1),
                "CENTER"
            ),
            (
                "TOPPADDING",
                (0, 0),
                (-1, -1),
                8
            ),
            (
                "BOTTOMPADDING",
                (0, 0),
                (-1, -1),
                8
            )
        ])
    )

    elementos.append(total_tabla)
    elementos.append(Spacer(1, 18))

    doc.build(elementos)

    buffer.seek(0)

    return buffer.getvalue()


